            tagline = "A community art project turns a forgotten bridge into a place of welcome.",
            parts = listOf(
                StoryPart(1, "Ribbons on the Rail", listOf("On her way to school, Lami noticed blue ribbons tied to the public noticeboard near the pedestrian bridge. Each carried a short message of thanks.", "The bridge had recently been cleaned, and residents had begun leaving notes for the workers who maintained it.", "Lami wondered who had started the idea.")),
                StoryPart(2, "The First Message", listOf("The community centre kept a photograph of the first ribbon, tied by a crossing guard after a neighbourhood clean-up.", "The guard explained that the ribbons were meant to recognise quiet acts of service, not to mark ownership of the bridge.", "Lami asked whether the project could become a supervised community art display.")),
                StoryPart(3, "Permission and Planning", listOf("The centre contacted the local authority to check what could safely be displayed and where attachments were allowed.", "The authority approved a temporary noticeboard installation away from the bridge railings and walking path.", "Students sketched designs that would not obstruct signs, access, or movement.")),
                StoryPart(4, "Messages from Many Streets", listOf("Residents submitted notes thanking cleaners, bus drivers, teachers, shopkeepers, and neighbours who helped others.", "The student team checked that each message was respectful and that contributors agreed before names were displayed.", "They noticed that many notes thanked people whose work was rarely mentioned.")),
                StoryPart(5, "A Missing Contributor", listOf("One message thanked an unnamed person who repaired a broken streetlight. The students wanted to include the worker but did not know the name.", "The centre contacted the maintenance office, which offered to pass along the message without sharing private staff details.", "The worker later sent a short reply saying the recognition meant a great deal.")),
                StoryPart(6, "The Colour Question", listOf("The team debated whether every ribbon should be blue. A younger student suggested adding different shades to represent different kinds of help.", "They agreed on one consistent blue background and small coloured marks for themes such as learning, care, and public service.", "The design remained simple enough to read from the path.")),
                StoryPart(7, "The Installation Day", listOf("With permission and adult supervision, the students installed the temporary display on the approved board.", "They checked that the board was stable, weather-resistant, and did not block access or emergency information.", "Residents stopped to read the messages and added more through the community centre.")),
                StoryPart(8, "A Quiet Disagreement", listOf("Two residents disagreed about a message that named a person who preferred privacy. The team paused the display update and contacted the contributor.", "The contributor chose to replace the name with a general thank-you. The students learned that appreciation should respect people's wishes.", "The centre added a clear review process for future submissions.")),
                StoryPart(9, "The Bridge Walk", listOf("At the community event, residents walked the route and read the display. The crossing guard explained how a small gesture had grown into a shared project.", "The students invited people to write messages for workers and volunteers who might never see public praise.", "The local authority asked the centre to share the project guidelines with other neighbourhood groups.")),
                StoryPart(10, "A Place of Welcome", listOf("The temporary display ended on schedule, and the students archived approved messages with permission.", "The community centre kept the project open for future events, using the same privacy and accessibility checks.", "Lami crossed the bridge the next morning. The ribbons were gone, but the habit remained: people had learned to notice one another's contributions and say thank you clearly."))
